	if art == "vorgang":
		return f"/portal/anfragen/{o.name}"
	if art == "flaeche":
		return f"/portal/flaechen/{o.name}"
	if art == "projekt":
		return f"/portal/projekte/{o.name}"
	if art == "interesse":
		return f"/portal/boerse/{o.projekt_id}"
	return f"/portal/nachrichten?bezug=nutzer:{o.name}"

