cd /c/Users/SALEADMIN/Downloads/Oekoinvest-Web/Import-Frappe/oekoinvest_app/oekoinvest_app/plattform/doctype && python - <<'EOF'
import json, pathlib, re, ast
docs = {}
for p in pathlib.Path(".").glob("*/*.json"):
    d = json.load(open(p, encoding="utf-8")); docs[d["name"]] = (p, d)
kern = {"User", "Role", "File", "DocType"}
fehler = []
for name, (p, d) in docs.items():
    felder = {f["fieldname"]: f for f in d["fields"]}
    if d["field_order"] != [f["fieldname"] for f in d["fields"]]: fehler.append((name, "field_order"))
    if len(felder) != len(d["fields"]): fehler.append((name, "doppelte Felder"))
    for f in d["fields"]:
        ft = f["fieldtype"]
        if ft == "Link" and f["options"] not in docs and f["options"] not in kern: fehler.append((name, f["fieldname"], f["options"]))
        if ft in ("Table", "Table MultiSelect"):
            ziel = docs.get(f["options"])
            if not ziel or not ziel[1].get("istable"): fehler.append((name, f["fieldname"], "kein Kindtyp"))
            if ft == "Table MultiSelect" and not any(x["fieldtype"] == "Link" for x in ziel[1]["fields"]): fehler.append((name, "MultiSelect ohne Link"))
        if ft == "Dynamic Link" and felder.get(f["options"], {}).get("fieldtype") != "Link": fehler.append((name, f["fieldname"], "Dynamic Link"))
        if not re.match(r"^[a-z][a-z0-9_]*$", f["fieldname"]): fehler.append((name, f["fieldname"], "name"))
    for k in ("title_field", "sort_field"):
        if d.get(k) and d[k] not in felder and d[k] not in ("creation", "modified"): fehler.append((name, k))
    if d.get("autoname", "").startswith("field:") and d["autoname"][6:] not in felder: fehler.append((name, "autoname"))
    if not d.get("istable") and not d.get("track_changes"): fehler.append((name, "track_changes"))
    if not d.get("istable") and not any(x.get("in_list_view") for x in d["fields"]): fehler.append((name, "keine Listenansicht"))
    py = p.with_suffix(".py"); klasse = name.replace(" ", "")
    baum = ast.parse(py.read_text(encoding="utf-8"))
    if not any(isinstance(x, ast.ClassDef) and x.name == klasse for x in baum.body): fehler.append((name, "Klasse", klasse))
    if d["module"] != "Plattform": fehler.append((name, "module"))
    if any("allow_guest" in json.dumps(x) for x in d["permissions"]): fehler.append((name, "guest"))
print(len(docs), "DocTypes;", "Fehler:", fehler or "keine")
EOF

